create type public.app_role as enum ('parent','community_relay','moderator','partner_manager','admin');
create type public.child_sex as enum ('female','male','unspecified');
create type public.measurement_source as enum ('parent','health_worker','imported');
create type public.immunization_status as enum ('due','scheduled','received','missed','declined');
create type public.content_status as enum ('draft','in_review','published','archived');
create table public.zones (id uuid primary key default gen_random_uuid(), parent_id uuid references public.zones(id), name text not null, level text not null, country_code text not null default 'CM', created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, preferred_language text not null default 'fr', primary_zone_id uuid references public.zones(id), created_at timestamptz not null default now());
create table public.user_roles (user_id uuid references public.profiles(id) on delete cascade, role public.app_role not null, primary key(user_id,role));
create table public.children (id uuid primary key default gen_random_uuid(), full_name text not null, date_of_birth date not null, sex public.child_sex not null, zone_id uuid references public.zones(id), created_at timestamptz not null default now());
create table public.child_guardians (child_id uuid references public.children(id) on delete cascade, user_id uuid references public.profiles(id) on delete cascade, relationship text not null default 'parent', is_owner boolean not null default false, primary key(child_id,user_id));
create table public.measurements (id uuid primary key default gen_random_uuid(), child_id uuid not null references public.children(id) on delete cascade, measured_at date not null, weight_kg numeric(4,2), height_cm numeric(5,2), head_circumference_cm numeric(4,1), source public.measurement_source not null default 'parent', note text, created_at timestamptz not null default now(), check(weight_kg is not null or height_cm is not null or head_circumference_cm is not null));
create table public.immunization_schedules (id uuid primary key default gen_random_uuid(), country_code text not null default 'CM', version text not null, valid_from date not null, valid_to date);
create table public.vaccine_doses (id uuid primary key default gen_random_uuid(), schedule_id uuid not null references public.immunization_schedules(id), code text not null, name text not null, due_age_days integer not null, unique(schedule_id,code));
create table public.child_immunizations (id uuid primary key default gen_random_uuid(), child_id uuid not null references public.children(id) on delete cascade, vaccine_dose_id uuid not null references public.vaccine_doses(id), status public.immunization_status not null default 'due', due_at date, received_at date, facility_name text, unique(child_id,vaccine_dose_id));
create table public.development_milestones (id uuid primary key default gen_random_uuid(), code text unique not null, domain text not null, min_age_months smallint not null, max_age_months smallint not null);
create table public.child_milestone_observations (child_id uuid references public.children(id) on delete cascade, milestone_id uuid references public.development_milestones(id), observed_at date, primary key(child_id,milestone_id));
create index measurements_child_date on public.measurements(child_id,measured_at desc); create index immunizations_due on public.child_immunizations(child_id,status,due_at); create index zones_parent on public.zones(parent_id);
alter table public.children enable row level security; alter table public.child_guardians enable row level security; alter table public.measurements enable row level security; alter table public.child_immunizations enable row level security; alter table public.child_milestone_observations enable row level security;
create policy "guardians manage child" on public.children for all using (exists(select 1 from public.child_guardians g where g.child_id=id and g.user_id=auth.uid())) with check (true);
create policy "guardians manage links" on public.child_guardians for all using (user_id=auth.uid()) with check (user_id=auth.uid());
create policy "guardians manage measurements" on public.measurements for all using (exists(select 1 from public.child_guardians g where g.child_id=measurements.child_id and g.user_id=auth.uid())) with check (exists(select 1 from public.child_guardians g where g.child_id=measurements.child_id and g.user_id=auth.uid()));
create policy "guardians manage immunizations" on public.child_immunizations for all using (exists(select 1 from public.child_guardians g where g.child_id=child_immunizations.child_id and g.user_id=auth.uid())) with check (exists(select 1 from public.child_guardians g where g.child_id=child_immunizations.child_id and g.user_id=auth.uid()));
